// The app's logo ("Zatáčka": a winding special stage with the finish flag, dark
// background). One source for the icon in the app (header, intro, Stories
// picture) and the files in web/public (favicon, home-screen and Android icons,
// og-image), generated by `npm run icons`. No DOM here.

/**
 * The logo as SVG markup, 512×512. `radius` rounds the corners (favicon; app
 * icons stay square, the OS masks them); `scale` shrinks the drawing inside
 * the background (Android's maskable icon keeps it in the central circle).
 */
export function logoSvg({ radius = 0, scale = 0.8 }: { radius?: number; scale?: number } = {}): string {
  const road = "M120 440 C120 330 392 330 392 250 S120 170 160 92";
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512"><defs><linearGradient id="zk-road" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#e11d2e"/><stop offset="1" stop-color="#ff7a18"/></linearGradient></defs><rect width="512" height="512" rx="${radius}" fill="#0b0d14"/><g transform="translate(256 262) scale(${scale}) translate(-256 -262)"><path d="${road}" fill="none" stroke="url(#zk-road)" stroke-width="78" stroke-linecap="round"/><path d="${road}" fill="none" stroke="#fff" stroke-width="8" stroke-linecap="round" stroke-dasharray="26 30" opacity=".9"/><g transform="translate(300 54)"><rect width="10" height="120" rx="5" fill="#fff"/><rect x="10" y="4" width="96" height="64" rx="6" fill="#fff"/><g fill="#0b0d14"><rect x="10" y="4" width="24" height="21"/><rect x="58" y="4" width="24" height="21"/><rect x="34" y="25" width="24" height="22"/><rect x="82" y="25" width="24" height="22"/><rect x="10" y="47" width="24" height="21"/><rect x="58" y="47" width="24" height="21"/></g></g></g></svg>`;
}

/** The logo as a data: URL (an <img> or a canvas image). */
export function logoDataUrl(options?: Parameters<typeof logoSvg>[0]): string {
  return `data:image/svg+xml;charset=utf-8,${encodeURIComponent(logoSvg(options))}`;
}
